{"python":"def pilot_policy(trace):
    import json
    current_action, current_label = trace[-1]
    action_name = current_action.name
    args = json.loads(current_action.arguments)
    label_subset = current_label.subset
    policy_slots = {
        'slot:assessor': {'PRICING', 'ACCESS'},
        'slot:escrow': {'ACCESS', 'UNSCREENED'},
        'slot:oversight': {'UNSCREENED'},
        'slot:public': {'CUSTOMER', 'PRICING', 'ACCESS'},
        'slot:supplier': {'CUSTOMER', 'ACCESS'}
    }
    # Determine agent from action_name
    if action_name.startswith('onboarding/'):
        agent = 'onboarding'
    elif action_name.startswith('analyst/'):
        agent = 'analyst'
    elif action_name.startswith('coordinator/'):
        agent = 'coordinator'
    elif action_name.startswith('procurement/'):
        agent = 'procurement'
    elif action_name.startswith('compliance/'):
        agent = 'compliance'
    else:
        raise PolicyViolation(f'Unknown tool: {action_name}')

    if action_name == 'onboarding/receive_record':
        category = args.get('category')
        if category is None or category not in {'CUSTOMER', 'PRICING', 'ACCESS', 'UNSCREENED'}:
            raise PolicyViolation('Invalid receive_record category')
        # Writes to slot:case (not in policy, so allowed)
        return None
    elif action_name == 'analyst/verify_case':
        # Writes to slot:verified (not in policy, so allowed)
        return None
    elif action_name == 'coordinator/bundle_case':
        source = args.get('source')
        if source not in {'verified', 'case'}:
            raise PolicyViolation('Invalid bundle_case source')
        # Writes to slot:package (not in policy, so allowed)
        return None
    elif action_name in {'procurement/transfer_case', 'compliance/transfer_case'}:
        source = args.get('source')
        recipient = args.get('recipient')
        enclosure = args.get('enclosure')
        replica = args.get('replica')
        # Determine destination slots based on agent and parameters
        dest_slots = set()
        # Determine primary recipient slot
        if agent == 'procurement':
            if recipient == 'local':
                dest_slots.add('slot:operations')
            elif recipient == 'partner':
                dest_slots.add('slot:supplier')
            elif recipient == 'oversight':
                dest_slots.add('slot:oversight')
            else:
                raise PolicyViolation('Invalid recipient for procurement')
        elif agent == 'compliance':
            if recipient == 'local':
                dest_slots.add('slot:operations')
            elif recipient == 'partner':
                dest_slots.add('slot:assessor')
            elif recipient == 'oversight':
                dest_slots.add('slot:oversight')
            else:
                raise PolicyViolation('Invalid recipient for compliance')
        # Determine replica slot
        if replica == 'escrow':
            dest_slots.add('slot:escrow')
        elif replica == 'public':
            dest_slots.add('slot:public')
        elif replica == 'partner':
            if agent == 'procurement':
                dest_slots.add('slot:supplier')
            elif agent == 'compliance':
                dest_slots.add('slot:assessor')
        # For each destination slot not in policy, no restriction; for those in policy, check label_subset is subset of allowed
        for slot in dest_slots:
            if slot in policy_slots:
                allowed = policy_slots[slot]
                if not label_subset.issubset(allowed):
                    raise PolicyViolation(f'Label {label_subset} not allowed in {slot}')
        return None
    else:
        raise PolicyViolation(f'Unexpected tool: {action_name}')}"}
